"""Record the inspected contextual hat conversion and advance only its authoring gate."""
from pathlib import Path
from datetime import datetime, timezone
import hashlib, json
HERE=Path(__file__).resolve().parent; ROOT=HERE.parents[3]
def ref(p):return dict(path=p.relative_to(ROOT).as_posix(),sha256=hashlib.sha256(p.read_bytes()).hexdigest())
def write(p,d):p.write_bytes((json.dumps(d,indent=2)+'\n').encode())
def refs(*names):return [ref(HERE/n) for n in names]
ledger_path=ROOT/'evidence/conversion-ledger.json';ledger=json.loads(ledger_path.read_text())
entry=next(e for e in ledger['entries'] if e['id']=='FIT-HUMAN-FEMALE-WIDE-BRIMMED-HAT-HEAD-0')
assert ledger['active_entry']==entry['id'] and not entry.get('generation_ready')
review='Inspected full crown/brim, unchanged original head, cardinal SEN and mirrored west, complete neutral hat, native y primary / b band separation and 48x96 intended-size assembly. Worn creases and salt stains derive from the actual contextual output; backdrop, red mannequin and generated body contours are excluded. Zero body-over-hat visibility is intentional: original skin never overwrites hat. No sleeve fitting or extra isolation call. Native outfit/equipment acceptance remains pending the full generation set.'
write(HERE/'authoring-review.json',dict(status='GENERATION READY',workflow='regional-curved-v1',review=review,inspected=refs('headwear-comparison.png','intact-garment-comparison.png','independent-palette-comparison.png','game-scale-review.png'),native_acceptance='Pending all-conversions generation gate'))
write(HERE/'artifact-manifest.json',dict(entry=entry['id'],files=[ref(p) for p in sorted(HERE.iterdir()) if p.is_file() and p.name!='artifact-manifest.json']))
def event(step,action,inputs,outputs,**extra):
 entry['process_log'].append(dict(timestamp=datetime.now(timezone.utc).isoformat(),step=step,action=action,inputs=inputs,outputs=outputs,review=review,result='PASS',**extra))
event('imagegen_refine_in_context_on_unchanged_body','Refined the constructed enlarged red head contexts once, with the actual original Qud hat and RimWorld CowboyHat reference. Generated mannequin is not the body source.',refs('constructed-red-head-context.png','source-packet.json','imagegen-prompt.txt'),refs('refined-red-context.png'),tool='image_gen.imagegen',prompt=(HERE/'imagegen-prompt.txt').read_text(),settings=dict(transparent_background=True,referenced_image_paths=['constructed-red-head-context.png','E:/Temp/qud-transplant-probe-pawns-20261019/donor/village-originals/wide-brimmed-hat-reference.png','E:/Temp/qud-transplant-probe-pawns-20261019/donor/worn-hat-south.png']),new_imagegen_call=True)
event('retrieve_isolated_item_and_masks','Mapped the same contextual material into the complete constructed hat, excluded red/backdrop and continued missing surface before restoring its authored contour. No second generative isolation. Retained neutral full hat and independent lower-band detail.',refs('register-hat.py','refined-red-context.png','source-packet.json'),refs('registration-decisions.json','intact-garment-comparison.png','continuation-comparison.png','band-detail-comparison.png','body-overlay-comparison.png'))
event('recompose_check_cuffs_attachment_occlusion_all_views','Composed complete hat above the original registered head in SEN and mirrored west. Identity fit already matches head landmarks; zero body visibility and empty overlay explicitly retain skin behind headwear.',refs('register-hat.py','registration-decisions.json'),refs('model.json','headwear-comparison.png','assembly-comparison.png'))
event('review_game_scale_and_palette','Reviewed intended-size facings and independent y-primary, b-band palette; body C is illustrative and separate.',refs('model.json'),refs('independent-palette-comparison.png','game-scale-review.png','authoring-review.json'))
event('reprocess_under_regional_curved_v1','Completed this hat entry under the approved continuous-source workflow with class-specific head ownership, original body/frame and transparent item layers. Sleeve/arm masks and regional deformation were unnecessary for this source-bound hat.',refs('record-review.py','source-packet.json','registration-decisions.json'),refs('artifact-manifest.json','authoring-review.json'))
entry.update(status='UNFINISHED',generation_ready=True,current_step='native_equipment_state_review',current_registration=dict(model=ref(HERE/'model.json'),plate=ref(HERE/'headwear-comparison.png')),art_review=dict(status='PASS',reason=review),registration_summary='Full neutral creased crown/brim and separate native blue band on unchanged female head; zero skin overlay. SEN + mirrored west. Native acceptance pending.',native_acceptance='Pending final all-conversions gate')
entry['apparel_workflow']['status']='GENERATION READY'
nxt=next(e for e in ledger['entries'] if e['id']=='FIT-HUMAN-MALE-WIDE-BRIMMED-HAT-HEAD-0');assert nxt['status']=='UNFINISHED' and not nxt['generation_ready'];nxt.update(status='IN PROGRESS',current_step='source_identity_description_slot_laterality');ledger['active_entry']=nxt['id'];ledger['updated_at']=datetime.now(timezone.utc).isoformat();write(ledger_path,ledger)
print('Female hat authoring recorded; male hat is the sole active entry. Native acceptance pending.')
